const cfg = $input.first().json;
const state = $getWorkflowStaticData('global');

const cities = Array.isArray(cfg.cities) ? cfg.cities.filter(c => c?.city) : [];
const keywords = Array.isArray(cfg.keywords)
  ? cfg.keywords.map(k => String(k || '').trim()).filter(Boolean)
  : [];

if (!cities.length) throw new Error('No cities configured');
if (!keywords.length) throw new Error('No keywords configured');

const candidates = [];
for (const cityConfig of cities) {
  for (const category of keywords) {
    candidates.push({
      ...cityConfig,
      category,
      keyword: `${category} in ${cityConfig.city}, Pakistan`,
    });
  }
}

let cursor = Number(state.searchRotationCursor ?? 0);
if (!Number.isInteger(cursor) || cursor < 0 || cursor >= candidates.length) cursor = 0;

const requested = Math.max(1, Math.floor(Number(cfg?.limits?.keywordsPerRun || 1)));
const count = Math.min(requested, candidates.length);
const nextCursor = (cursor + count) % candidates.length;
const run = Number(state.searchRotationRuns ?? 0) + 1;

const out = [];
for (let i = 0; i < count; i++) {
  const index = (cursor + i) % candidates.length;
  out.push({
    json:{
      ...cfg,
      ...candidates[index],
      industry:cfg.niche,
      rotation:{
        index,
        position:index + 1,
        total:candidates.length,
        cursor_before:cursor,
        cursor_after:nextCursor,
        batch_position:i + 1,
        batch_size:count,
        run
      }
    }
  });
}

state.searchRotationCursor = nextCursor;
state.searchRotationRuns = run;
return out;

const out = [];

function clean(value) {
  const s = String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

  if (
    !s ||
    /^(?:n\/?a|na|none|null|unknown|-|—)$/i.test(s)
  ) {
    return '';
  }

  return s;
}

function normalizePhone(value) {
  const s = clean(value);

  if (!s) return '';

  const p = s.replace(/[^0-9+]/g, '');

  return p.length >= 7 ? p : '';
}

function normalizeWebsite(value) {
  let s = clean(value);

  if (!s) return '';

  s = s.replace(/&amp;/gi, '&');

  if (s.startsWith('//')) {
    s = `https:${s}`;
  }

  if (!/^https?:\/\//i.test(s)) {
    s = `https://${s}`;
  }

  /*
   * IMPORTANT:
   * Do NOT use new URL() here.
   *
   * Some n8n Code-node environments do not
   * expose the URL constructor as expected.
   */

  if (!/^https?:\/\/[^\s/]+(?:[/?#][^\s]*)?$/i.test(s)) {
    return '';
  }

  return s;
}

function getDomain(value) {
  const s = clean(value);

  if (!s) return '';

  /*
   * Extract hostname without new URL().
   *
   * Examples:
   *
   * http://propertyprimetime.net/
   * -> propertyprimetime.net
   *
   * https://www.tabanirealestate.com/
   * -> tabanirealestate.com
   *
   * https://www.facebook.com/profile.php?id=123
   * -> facebook.com
   */

  const match = s.match(
    /^https?:\/\/([^/?#\s]+)/i
  );

  if (!match || !match[1]) {
    return '';
  }

  return match[1]
    .replace(/^[^@]+@/, '')
    .replace(/:\d+$/, '')
    .replace(/^www\./i, '')
    .toLowerCase();
}

function normalizeMapsUrl(value) {
  /*
   * Backend already provides the Maps URL.
   * There is no reason to parse/rebuild it.
   */
  return clean(value);
}

function parsePossibleJson(value) {
  if (typeof value !== 'string') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

function extractResults(rawResponse) {
  let response = parsePossibleJson(rawResponse);

  /*
   * n8n may wrap HTTP response in body.
   */
  if (
    response &&
    response.body !== undefined
  ) {
    response =
      parsePossibleJson(response.body);
  }

  /*
   * Normal backend response:
   *
   * {
   *   success: true,
   *   data: {
   *     results: [...]
   *   }
   * }
   */
  if (
    Array.isArray(
      response?.data?.results
    )
  ) {
    return response.data.results;
  }

  /*
   * Direct search result object.
   */
  if (
    Array.isArray(
      response?.results
    )
  ) {
    return response.results;
  }

  /*
   * Extra wrapper fallback.
   */
  if (
    Array.isArray(
      response?.data?.data?.results
    )
  ) {
    return response.data.data.results;
  }

  /*
   * Direct array fallback.
   */
  if (Array.isArray(response)) {
    return response;
  }

  return [];
}


/*
 * ==========================================
 * PROCESS INPUT
 * ==========================================
 */

for (const item of $input.all()) {

  const j = item.json;

  const query =
    clean(j.keyword);

  if (!query) {

    out.push({
      json: {
        ...j,

        _skipUpsert: true,

        skipReason:
          'empty_search_keyword'
      }
    });

    continue;
  }


  const baseUrl =
    String(
      j.scraper?.baseUrl || ''
    ).replace(/\/$/, '');


  if (!baseUrl) {

    out.push({
      json: {
        ...j,

        _skipUpsert: true,

        skipReason:
          'missing_scraper_base_url'
      }
    });

    continue;
  }


  /*
   * ========================================
   * CALL GOOGLE MAPS SCRAPER
   * ========================================
   */

  let response;

  try {

    response =
      await this.helpers.httpRequest({

        method: 'POST',

        url:
          `${baseUrl}/api/scrape/search`,

        headers: {
          'Content-Type':
            'application/json'
        },

        body: {
          query,

          maxResults:
            Math.max(
              1,
              Math.min(
                12,
                Number(
                  j.limits
                    ?.maxResultsPerKeyword ||
                    12
                )
              )
            )
        },

        json: true,

        timeout: 240000
      });

  } catch (error) {

    out.push({
      json: {
        ...j,

        _skipUpsert: true,

        skipReason:
          'google_maps_scrape_failed',

        scrapeError:
          String(
            error?.message ||
            error
          )
      }
    });

    continue;
  }


  /*
   * ========================================
   * GET SCRAPER RESULTS
   * ========================================
   */

  const results =
    extractResults(response);


  if (!results.length) {

    out.push({
      json: {
        ...j,

        _skipUpsert: true,

        skipReason:
          'google_maps_no_results'
      }
    });

    continue;
  }


  /*
   * ========================================
   * PROCESS BUSINESSES
   * ========================================
   */

  let acceptedWithWebsite = 0;
  let rejectedNoWebsite = 0;
  let rejectedNoName = 0;
  let rejectedInvalidWebsite = 0;


  for (const rawPlace of results) {

    const p =
      parsePossibleJson(rawPlace) || {};


    /*
     * BUSINESS NAME
     */

    const businessName =
      clean(
        p.title ??
        p.name ??
        p.businessName
      );


    if (!businessName) {

      rejectedNoName++;

      continue;
    }


    /*
     * WEBSITE
     *
     * Website is mandatory.
     */

    const rawWebsite =
      clean(
        p.website ??
        p.businessWebsite ??
        p.websiteUrl ??
        p.websiteURL
      );


    if (!rawWebsite) {

      rejectedNoWebsite++;

      continue;
    }


    const businessWebsite =
      normalizeWebsite(
        rawWebsite
      );


    if (!businessWebsite) {

      rejectedInvalidWebsite++;

      continue;
    }


    const domain =
      getDomain(
        businessWebsite
      );


    if (!domain) {

      rejectedInvalidWebsite++;

      continue;
    }


    /*
     * PHONE
     */

    const businessPhone =
      normalizePhone(
        p.phone ??
        p.phoneNumber
      );


    /*
     * GOOGLE MAPS URL
     */

    const googleMapsUrl =
      normalizeMapsUrl(
        p.googleMapsUrl ??
        p.url ??
        p.mapsUrl
      );


    /*
     * EMAIL FROM MAPS
     */

    const mapEmail =
      clean(
        p.email
      ).toLowerCase();


    /*
     * LATITUDE
     */

    const latitude =
      Number.isFinite(
        Number(p.latitude)
      )
        ? Number(p.latitude)
        : null;


    /*
     * LONGITUDE
     */

    const longitude =
      Number.isFinite(
        Number(p.longitude)
      )
        ? Number(p.longitude)
        : null;


    /*
     * RATING
     */

    const rating =
      Number.isFinite(
        Number(p.rating)
      )
        ? Number(p.rating)
        : null;


    /*
     * REVIEWS
     */

    const reviews =
      Math.max(
        0,

        Number(
          String(
            p.reviews ?? ''
          ).replace(
            /[^0-9]/g,
            ''
          )
        ) || 0
      );


    /*
     * ======================================
     * ACCEPT BUSINESS
     * ======================================
     */

    acceptedWithWebsite++;


    out.push({
      json: {

        ...j,

        businessName,

        address:
          clean(
            p.address
          ),

        phone:
          businessPhone,

        /*
         * MANDATORY WEBSITE
         */
        website:
          businessWebsite,

        domain,

        googleMapsUrl,

        latitude,

        longitude,

        rating,

        reviews,

        rawCategory:
          clean(
            p.category ??
            j.category
          ),

        sourceRetrievedAt:
          new Date()
            .toISOString(),

        mapEmails:
          mapEmail
            ? [mapEmail]
            : []

      }
    });

  }


  /*
   * ========================================
   * ZERO ACCEPTED RESULTS
   * ========================================
   */

  if (acceptedWithWebsite === 0) {

    const firstResult =
      results.length
        ? parsePossibleJson(
            results[0]
          )
        : null;


    out.push({
      json: {

        ...j,

        _skipUpsert: true,

        skipReason:
          'google_maps_no_results_with_website',

        scraperResultsReceived:
          results.length,

        acceptedWithWebsite,

        rejectedNoWebsite,

        rejectedInvalidWebsite,

        rejectedNoName,

        firstResultFields:
          firstResult &&
          typeof firstResult ===
            'object'
            ? Object.keys(
                firstResult
              )
            : [],

        firstResultWebsite:
          clean(
            firstResult?.website
          )

      }
    });

  }

}

return out;

const inputs = $input.all();

/* =========================================================
 * HELPERS
 * ========================================================= */

function uniq(values) {
  return [...new Set(
    (values || []).filter(Boolean)
  )];
}

function clean(value) {
  const s = String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

  if (
    !s ||
    /^(?:n\/?a|na|none|null|unknown|-|—)$/i.test(s)
  ) {
    return '';
  }

  return s;
}

function htmlToText(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeEmail(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/^mailto:/i, '')
    .replace(/^[<(\"'\s]+/, '')
    .replace(/[>)\"'\],.;:\s]+$/, '');
}

function validEmailSyntax(email) {
  if (!email || email.length > 254) {
    return false;
  }

  const at = email.lastIndexOf('@');

  if (at <= 0) {
    return false;
  }

  const local = email.slice(0, at);
  const domain = email.slice(at + 1);

  if (
    !local ||
    !domain ||
    local.length > 64 ||
    domain.length > 253
  ) {
    return false;
  }

  if (
    local.startsWith('.') ||
    local.endsWith('.') ||
    local.includes('..')
  ) {
    return false;
  }

  if (
    !/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/i.test(local)
  ) {
    return false;
  }

  const labels = domain.split('.');

  if (labels.length < 2) {
    return false;
  }

  for (const label of labels) {
    if (
      !label ||
      label.length > 63 ||
      !/^[a-z0-9-]+$/i.test(label) ||
      label.startsWith('-') ||
      label.endsWith('-')
    ) {
      return false;
    }
  }

  return /^[a-z]{2,63}$/i.test(
    labels[labels.length - 1]
  );
}

function assetGarbage(email) {
  const lower =
    String(email || '').toLowerCase();

  const parts = lower.split('@');

  const local = parts[0] || '';
  const domain = parts[1] || '';

  return (
    /\.(?:png|jpe?g|gif|webp|svg|ico|css|js|woff2?|ttf|eot|pdf|zip)$/i
      .test(domain) ||

    /^(?:logo|icon|sprite|favicon|image|img|avatar|banner|thumbnail|thumb)(?:[-_.]|$)/i
      .test(local) ||

    /@(?:2x|3x)\.(?:png|jpe?g|gif|webp)$/i
      .test(lower)
  );
}

function sanitizeEmails(values) {
  return uniq(
    (values || [])
      .map(normalizeEmail)
      .filter(
        email =>
          validEmailSyntax(email) &&
          !assetGarbage(email)
      )
  );
}


/* =========================================================
 * PHONE / WHATSAPP
 * ========================================================= */

function normalizeMsisdn(value) {
  const digits =
    String(value || '')
      .replace(/[^0-9]/g, '');

  if (!digits) {
    return '';
  }

  if (digits.startsWith('92')) {
    return digits.slice(-10);
  }

  if (digits.startsWith('0')) {
    return digits.slice(-10);
  }

  return digits.slice(-10);
}

function isPakMobile(value) {
  const n = normalizeMsisdn(value);

  return /^3\d{9}$/.test(n);
}

function extractWaNumber(link) {
  const s = String(link || '');

  const match =
    s.match(
      /wa\.me\/(\+?\d{7,15})/i
    ) ||
    s.match(
      /[?&](?:phone|number)=(\+?\d{7,15})/i
    );

  return match
    ? match[1].replace(/[^0-9+]/g, '')
    : '';
}


/* =========================================================
 * URL HELPERS
 *
 * IMPORTANT:
 * NO new URL()
 * ========================================================= */

function normalizeWebsite(value) {
  let s = clean(value);

  if (!s) {
    return '';
  }

  s = s.replace(/&amp;/gi, '&');

  if (s.startsWith('//')) {
    s = `https:${s}`;
  }

  if (!/^https?:\/\//i.test(s)) {
    s = `https://${s}`;
  }

  if (!/^https?:\/\/[^\s/]+/i.test(s)) {
    return '';
  }

  return s;
}

function getOrigin(value) {
  const s = normalizeWebsite(value);

  if (!s) {
    return '';
  }

  const match =
    s.match(
      /^(https?):\/\/([^/?#\s]+)/i
    );

  if (!match) {
    return '';
  }

  return `${match[1].toLowerCase()}://${match[2]}`;
}

function getHostname(value) {
  const s = normalizeWebsite(value);

  if (!s) {
    return '';
  }

  const match =
    s.match(
      /^https?:\/\/([^/?#\s]+)/i
    );

  if (!match) {
    return '';
  }

  return match[1]
    .replace(/:\d+$/, '')
    .replace(/^www\./i, '')
    .toLowerCase();
}

function isFacebookUrl(value) {
  const host = getHostname(value);

  return (
    host === 'facebook.com' ||
    host.endsWith('.facebook.com') ||
    host === 'fb.com' ||
    host.endsWith('.fb.com')
  );
}

function isInstagramUrl(value) {
  const host = getHostname(value);

  return (
    host === 'instagram.com' ||
    host.endsWith('.instagram.com')
  );
}

function isLinkedinUrl(value) {
  const host = getHostname(value);

  return (
    host === 'linkedin.com' ||
    host.endsWith('.linkedin.com')
  );
}

function isSocialWebsite(value) {
  return (
    isFacebookUrl(value) ||
    isInstagramUrl(value) ||
    isLinkedinUrl(value)
  );
}


/* =========================================================
 * PAGE URL GENERATOR
 *
 * NO new URL()
 * ========================================================= */

function pageUrls(site, limit) {
  const website =
    normalizeWebsite(site);

  if (!website) {
    return [];
  }

  /*
   * If Google Maps supplied Facebook,
   * Instagram or LinkedIn as "website",
   * don't attempt /about, /contact etc.
   */
  if (isSocialWebsite(website)) {
    return [website];
  }

  const origin =
    getOrigin(website);

  if (!origin) {
    return [website];
  }

  const maxPages =
    Math.max(
      1,
      Math.min(
        6,
        Number(limit || 3)
      )
    );

  /*
   * Always crawl the EXACT URL Google Maps
   * supplied first.
   */
  const urls = [
    website,
    `${origin}/`,
    `${origin}/contact`,
    `${origin}/contact-us`,
    `${origin}/about`,
    `${origin}/about-us`
  ];

  return uniq(urls)
    .slice(0, maxPages);
}


/* =========================================================
 * HTML LINK EXTRACTION
 * ========================================================= */

function extractSocialProfiles(html, originalWebsite) {
  const source =
    String(html || '');

  let linkedin =
    source.match(
      /https?:\/\/(?:[a-z]{2,3}\.)?linkedin\.com\/(?:in|company)\/[A-Za-z0-9_%?&=#./-]+/gi
    ) || [];

  let facebook =
    source.match(
      /https?:\/\/(?:www\.|m\.)?facebook\.com\/[A-Za-z0-9_.?&=#%/-]+/gi
    ) || [];

  let instagram =
    source.match(
      /https?:\/\/(?:www\.)?instagram\.com\/[A-Za-z0-9_.?&=#%/-]+/gi
    ) || [];

  /*
   * Google Maps itself may provide a social
   * profile as the business website.
   */
  const original =
    normalizeWebsite(originalWebsite);

  if (original) {
    if (isFacebookUrl(original)) {
      facebook.push(original);
    }

    if (isInstagramUrl(original)) {
      instagram.push(original);
    }

    if (isLinkedinUrl(original)) {
      linkedin.push(original);
    }
  }

  return {
    linkedin: uniq(linkedin),
    facebook: uniq(facebook),
    instagram: uniq(instagram)
  };
}

function extractWhatsappLinks(html) {
  const source =
    String(html || '');

  const links = [];

  const patterns = [
    /https?:\/\/wa\.me\/[0-9+][0-9]{6,15}[^\s"'<>]*/gi,

    /https?:\/\/api\.whatsapp\.com\/send[^\s"'<>]*/gi,

    /https?:\/\/(?:www\.)?whatsapp\.com\/send[^\s"'<>]*/gi,

    /whatsapp:\/\/send\?[^\s"'<>]*/gi
  ];

  for (const pattern of patterns) {
    const found =
      source.match(pattern) || [];

    links.push(...found);
  }

  return uniq(
    links.map(
      link =>
        String(link)
          .replace(/&amp;/gi, '&')
          .replace(/[),.;]+$/, '')
    )
  );
}


/* =========================================================
 * HTTP FETCH
 * ========================================================= */

async function fetchPage(url) {
  try {
    const response =
      await this.helpers.httpRequest({

        method: 'GET',

        url,

        timeout: 15000,

        followRedirect: true,

        maxRedirects: 8,

        headers: {
          'User-Agent':
            'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',

          'Accept':
            'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',

          'Accept-Language':
            'en-US,en;q=0.9',

          'Cache-Control':
            'no-cache',

          'Pragma':
            'no-cache'
        },

        json: false
      });

    const html =
      String(response || '');

    if (!html.trim()) {
      return {
        ok: false,
        url,
        html: '',
        error: 'empty_response'
      };
    }

    return {
      ok: true,
      url,
      html,
      error: ''
    };

  } catch (error) {

    return {
      ok: false,
      url,
      html: '',
      error:
        String(
          error?.message ||
          error
        ).slice(0, 500)
    };
  }
}


/* =========================================================
 * CONCURRENCY
 * ========================================================= */

async function mapLimit(
  items,
  limit,
  worker
) {
  const results =
    new Array(items.length);

  let cursor = 0;

  async function run() {
    while (true) {
      const i = cursor++;

      if (i >= items.length) {
        return;
      }

      results[i] =
        await worker(items[i], i);
    }
  }

  await Promise.all(
    Array.from(
      {
        length:
          Math.min(
            limit,
            items.length
          )
      },
      run
    )
  );

  return results;
}


/* =========================================================
 * MAIN
 * ========================================================= */

const concurrency =
  Math.max(
    1,
    Math.min(
      5,
      Number(
        inputs[0]
          ?.json
          ?.limits
          ?.websiteConcurrency ||
        3
      )
    )
  );


const results =
  await mapLimit(
    inputs,
    concurrency,

    async item => {

      const j = item.json;


      /*
       * Preserve an upstream skip only when
       * there really was no usable Maps lead.
       */
      if (j._skipUpsert === true) {

        return {
          json: {
            ...j,

            emails: [],

            socialProfiles: {
              linkedin: [],
              facebook: [],
              instagram: []
            },

            websiteText: '',

            websiteSignals: {
              hasWebsite:
                !!clean(j.website),

              websiteReachable:
                false,

              emailCandidateCount:
                0,

              emailCount:
                0,

              linkedinCount:
                0,

              pagesAttempted:
                [],

              pagesCrawled:
                []
            },

            whatsappSignals: {
              hasClickToChat:
                false,

              links: [],

              numbers: [],

              matchesListedPhone:
                false,

              phoneType:
                j.phone
                  ? (
                      isPakMobile(j.phone)
                        ? 'mobile'
                        : 'landline_or_other'
                    )
                  : 'unknown'
            },

            socialPlatformCount:
              0,

            contacts: []
          }
        };
      }


      /*
       * =====================================
       * WEBSITE
       * =====================================
       */

      const website =
        normalizeWebsite(
          j.website
        );


      /*
       * Website remains mandatory.
       */
      if (!website) {

        return {
          json: {
            ...j,

            _skipUpsert: true,

