  if (Array.isArray(j.emails) && j.emails.length) s += 10;
  if (j.socialProfiles?.linkedin?.length) s += 5;
  if (j.socialProfiles?.facebook?.length) s += 5;
  if (j.socialProfiles?.instagram?.length) s += 5;
  if ((j.reviews || 0) >= 50) s += 5;
  if ((j.reviews || 0) >= 200) s += 5;
  if ((j.rating || 0) >= 4) s += 5;
  if (j.whatsappSignals?.hasClickToChat) s += 20;
  else if (j.whatsappSignals?.phoneType === 'mobile' && (j.socialPlatformCount || 0) >= 1) s += 10;
  return Math.min(100, s);
}
function gradeFor(score) {
  return score >= 80 ? 'A' : score >= 65 ? 'B' : score >= 45 ? 'C' : 'D';
}
// WhatsApp is never "confirmed" from a cold scrape without messaging the number (which
// requires opt-in / an approved template under Meta's policy). "Confirmed" here means we
// found real, public evidence the business already runs WhatsApp for customer contact
// (a wa.me / click-to-chat link on their own site). "Capable" just means the number could
// technically be a WhatsApp number (it's mobile, not a landline).
function whatsappConfirmedFor(j) {
  return !!(j.whatsappSignals?.hasClickToChat);
}
function whatsappCapableFor(j) {
  return !!(j.whatsappSignals?.hasClickToChat || j.whatsappSignals?.phoneType === 'mobile');
}
function metaCrmFitFor(j, score) {
  const social = j.socialPlatformCount || 0;
  const waWeight = whatsappConfirmedFor(j) ? 2 : (whatsappCapableFor(j) ? 1 : 0);
  const composite = score + social * 8 + waWeight * 15;
  if (composite >= 95 && waWeight >= 1 && social >= 1) return 'high';
  if (composite >= 65) return 'medium';
  return 'low';
}
function conversionTierFor(j, score) {
  const social = j.socialPlatformCount || 0;
  if (whatsappConfirmedFor(j) && score >= 80 && social >= 1) return 'tier1_high_conversion';
  if (whatsappCapableFor(j) && score >= 65 && social >= 1) return 'tier2_medium_conversion';
  return 'tier3_low_conversion';
}
function socialActivityScoreFor(j) {
  return Math.min(100, (j.socialPlatformCount || 0) * 25 + Math.min(50, Math.round((j.reviews || 0) / 10)));
}
