const mxCache = new Map();

function clean(v) {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (!s || /^(?:n\/?a|na|none|null|unknown|-|—)$/i.test(s)) return '';
  return s;
}
function cleanPhone(v) {
  const s = clean(v);
  if (!s) return '';
  const p = s.replace(/[^0-9+]/g, '');
  return p.length >= 7 ? p : '';
}
function normalizeEmail(v) {
  return String(v || '').trim().toLowerCase().replace(/^mailto:/i, '').replace(/^[<(\"'\s]+/, '').replace(/[>)\"'\],.;:\s]+$/, '');
}
function validSyntax(email) {
  if (!email || email.length > 254) return false;
  const at = email.lastIndexOf('@');
  if (at <= 0) return false;
  const local = email.slice(0, at), domain = email.slice(at + 1);
  if (!local || !domain || local.length > 64 || domain.length > 253) return false;
  if (local.startsWith('.') || local.endsWith('.') || local.includes('..')) return false;
  if (!/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/i.test(local)) return false;
  const labels = domain.split('.');
  if (labels.length < 2) return false;
  for (const label of labels) {
    if (!label || label.length > 63 || !/^[a-z0-9-]+$/i.test(label) || label.startsWith('-') || label.endsWith('-')) return false;
  }
  return /^[a-z]{2,63}$/i.test(labels.at(-1));
}
function assetGarbage(email) {
  const lower = email.toLowerCase();
  const [local='', domain=''] = lower.split('@');
  return /\.(?:png|jpe?g|gif|webp|svg|ico|css|js|woff2?|ttf|eot|pdf|zip)$/i.test(domain) ||
    /^(?:logo|icon|sprite|favicon|image|img|avatar|banner|thumbnail|thumb)(?:[-_.]|$)/i.test(local) ||
    /@(?:2x|3x)\.(?:png|jpe?g|gif|webp)$/i.test(lower);
}
async function mxFor(domain) {
  if (mxCache.has(domain)) return mxCache.get(domain);
  let result;
  try {
    const r = await this.helpers.httpRequest({
      method:'GET',
      url:'https://dns.google/resolve',
      qs:{name:domain,type:'MX'},
      headers:{Accept:'application/dns-json'},
      json:true,
      timeout:8000
    });
    const answers = Array.isArray(r?.Answer) ? r.Answer : [];
    const records = answers.filter(x => Number(x.type) === 15).map(x => String(x.data || '').trim()).filter(Boolean);
    const nullMx = records.some(x => /^0\s+\.$/.test(x));
    result = {valid:records.length > 0 && !nullMx,records,reason:nullMx?'null_mx':records.length?'mx_found':'no_mx'};
  } catch (e) {
    result = {valid:false,records:[],reason:`dns_error:${String(e.message || e)}`};
  }
  mxCache.set(domain, result);
  return result;
}
async function validateEmail(raw) {
  const email = normalizeEmail(raw);
  if (!validSyntax(email)) return {email,valid:false,syntax_valid:false,mx_valid:false,mx_records:[],reason:'invalid_syntax'};
  if (assetGarbage(email)) return {email,valid:false,syntax_valid:true,mx_valid:false,mx_records:[],reason:'asset_or_scraper_junk'};
  const mx = await mxFor(email.split('@')[1]);
  return {email,valid:mx.valid,syntax_valid:true,mx_valid:mx.valid,mx_records:mx.records,reason:mx.reason};
}
async function mapLimit(items, limit, worker) {
  const results = new Array(items.length);
